/**
 * Takes player names out of recorded text, for the "Hide player names" setting. Jagex names are matched
 * however the game writes them: any case, and with spaces, non-breaking spaces, underscores or hyphens
 * between their words.
 */
final class Names
{
	static final String HIDDEN = "<player>";

	private Names()
	{
	}

	static String scrub(String text, Collection<String> names)
	{
		if (text == null || text.isEmpty() || names.isEmpty())
		{
			return text;
		}
		// Longer names first, so "Bob Smith" goes before "Bob"
		List<String> sorted = new ArrayList<>(names);
		sorted.sort((a, b) -> b.length() - a.length());
		String out = text;
		for (String name : sorted)
		{
			Pattern p = pattern(name);
			if (p != null)
			{
				out = p.matcher(out).replaceAll(Matcher.quoteReplacement(HIDDEN));
			}
		}
		return out;
	}

	private static Pattern pattern(String name)
	{
		String[] words = name.replace(' ', ' ').trim().split("[ _-]+");
		StringBuilder re = new StringBuilder("(?<![A-Za-z0-9])");
		int kept = 0;
		for (String word : words)
		{
			if (word.isEmpty())
			{
				continue;
			}
			if (kept++ > 0)
			{
				re.append("[ _\\u00A0-]");
			}
			re.append(Pattern.quote(word));
		}
		return kept == 0 ? null : Pattern.compile(re.append("(?![A-Za-z0-9])").toString(), Pattern.CASE_INSENSITIVE);
	}
}

package com.encounterrecorder;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicLong;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * One recording session: a JSON-lines file written on its own thread. Lines are queued on the client
 * thread and handed over once per tick, so the client thread never touches the disk.
 */
@Slf4j
class Recording
{
	interface Directory
	{
		Filepath get() throws IOException;
	}

	private static final DateTimeFormatter FILE_TIME = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	private final Gson gson;
	private final ExecutorService writer;
	private List<JsonObject> pending = new ArrayList<>();
	private BufferedWriter out;
	private volatile boolean failed;

	@Getter
	private volatile String fileName;
	@Getter
	private final boolean automatic;
	/**
	 * The NPC IDs that keep an automatic recording alive
	 */
	@Getter
	private final Set<Integer> watchedNpcIds;
	@Getter
	private int ticks;
	@Getter
	private long lines;
	private final AtomicLong bytes = new AtomicLong();
	@Getter
	private volatile Filepath file;

	int ticksSinceWatchedNpc;

	Recording(Gson gson, Directory directory, String label, boolean automatic, Set<Integer> watchedNpcIds)
	{
		this.gson = gson;
		this.automatic = automatic;
		this.watchedNpcIds = watchedNpcIds;
		this.fileName = FILE_TIME.format(LocalDateTime.now()) + "-" + safeLabel(label) + ".jsonl";
		this.writer = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "encounter-recorder");
			t.setDaemon(true);
			return t;
		});
		writer.execute(() ->
		{
			try
			{
				Filepath dir = directory.get().joinSegment("sessions");
				dir.createDirectories();
				// A name already in the folder gets the next number: TFA, TFA-1, TFA-2...
				fileName = Recordings.numbered(Recordings.names(dir), fileName, null);
				file = dir.joinSegment(fileName);
				out = file.openBufferedWriter(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
			}
			catch (IOException | IllegalArgumentException e)
			{
				log.warn("Could not open recording {}", fileName, e);
				failed = true;
			}
		});
	}

	/**
	 * Keeps letters, digits and dashes so the label is safe in a file name on every OS
	 */
	static String safeLabel(String label)
	{
		String cleaned = label == null ? "" : label.trim().replaceAll("[^A-Za-z0-9-]+", "-").replaceAll("-{2,}", "-").replaceAll("^-|-$", "");
		if (cleaned.isEmpty())
		{
			return "session";
		}
		return cleaned.length() > 40 ? cleaned.substring(0, 40) : cleaned;
	}

	void add(JsonObject line)
	{
		pending.add(line);
		lines++;
	}

	void endTick()
	{
		ticks++;
		flush();
	}

	long bytesWritten()
	{
		return bytes.get();
	}

	boolean hasFailed()
	{
		return failed;
	}

	private void flush()
	{
		if (pending.isEmpty())
		{
			return;
		}
		List<JsonObject> batch = pending;
		pending = new ArrayList<>();
		writer.execute(() -> write(batch));
	}

	private void write(List<JsonObject> batch)
	{
		if (failed || out == null)
		{
			return;
		}
		try
		{
			for (JsonObject line : batch)
			{
				String text = gson.toJson(line);
				out.write(text);
				out.write('\n');
				bytes.addAndGet(text.length() + 1);
			}
			out.flush();
		}
		catch (IOException e)
		{
			log.warn("Recording {} stopped writing", fileName, e);
			failed = true;
		}
	}

	/**
	 * Writes what is queued, closes the file and lets the writer thread finish on its own
	 */
	void close()
	{
		flush();
		writer.execute(() ->
		{
			if (out == null)
			{
				return;
			}
			try
			{
				out.close();
			}
			catch (IOException e)
			{
				log.warn("Could not close recording {}", fileName, e);
			}
		});
		writer.shutdown();
	}
}

package com.encounterrecorder;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Says that a recording is running and nothing more: it carries no fight information
 */
class RecordingOverlay extends OverlayPanel
{
	private final EncounterRecorderPlugin plugin;
	private final EncounterRecorderConfig config;

	@Inject
	RecordingOverlay(EncounterRecorderPlugin plugin, EncounterRecorderConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Recording recording = plugin.getRecording();
		if (recording == null || !config.showIndicator())
		{
			return null;
		}
		panelComponent.getChildren().add(LineComponent.builder()
			.left("● REC")
			.leftColor(recording.hasFailed() ? Color.ORANGE : Color.RED)
			.right(recording.isAutomatic() ? "auto" : "")
			.build());
		return super.render(graphics);
	}
}

package com.encounterrecorder;

import java.io.BufferedReader;
import java.io.IOException;
import java.util.Collection;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/**
 * The recordings in the sessions folder, for the panel's list: newest first, each shown by the name it was
 * given, without the time stamp in front or the .jsonl after it.
 */
final class Recordings
{
	private static final Pattern FILE = Pattern.compile("^(\\d{8}-\\d{6})-(.*)\\.jsonl$");
	/** A repeated name's number: "TFA_1" in the file, shown as "TFA-1" (labels never hold "_") */
	private static final Pattern COUNTED = Pattern.compile("^(.*)_(\\d+)$");
	private static final Pattern HEADER = Pattern.compile("\"e\"\\s*:\\s*\"header\"");
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");
	private static final DateTimeFormatter SHOWN = DateTimeFormatter.ofPattern("d MMM yyyy, HH:mm");

	static final class Entry
	{
		final String fileName;
		final String name;
		/** When it was recorded, from its file name, or when the file last changed */
		final LocalDateTime when;
		final long bytes;

		Entry(String fileName, String name, LocalDateTime when, long bytes)
		{
			this.fileName = fileName;
			this.name = name;
			this.when = when;
			this.bytes = bytes;
		}

		String describe()
		{
			return String.format("%s · %s · %,d KB", SHOWN.format(when), fileName, Math.max(1, bytes / 1024));
		}
	}

	private Recordings()
	{
	}

	static List<Entry> list(Filepath dir) throws IOException
	{
		List<Entry> out = new ArrayList<>();
		for (Filepath f : files(dir))
		{
			out.add(entry(f.getFileName(), f.getLastModifiedTime().toMillis(), f.size()));
		}
		out.sort(Comparator.comparing((Entry e) -> e.when).reversed().thenComparing(e -> e.fileName));
		return out;
	}

	/** The names of the recordings in the folder */
	static List<String> names(Filepath dir) throws IOException
	{
		return files(dir).stream().map(Filepath::getFileName).collect(Collectors.toList());
	}

	private static List<Filepath> files(Filepath dir) throws IOException
	{
		if (!dir.isDirectory())
		{
			return new ArrayList<>();
		}
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(f -> f.getFileName().endsWith(".jsonl") && f.isFile()).collect(Collectors.toList());
		}
	}

	static Entry entry(String fileName, long modifiedMs, long bytes)
	{
		Matcher m = FILE.matcher(fileName);
		LocalDateTime when = null;
		String name = fileName.endsWith(".jsonl") ? fileName.substring(0, fileName.length() - ".jsonl".length()) : fileName;
		if (m.matches())
		{
			// The recorder turns spaces in a session's name into hyphens; turn them back for showing
			name = shownName(m.group(2));
			try
			{
				when = LocalDateTime.parse(m.group(1), STAMP);
			}
			catch (DateTimeParseException e)
			{
				// Not a time after all: fall back on the file's
			}
		}
		if (when == null)
		{
			when = LocalDateTime.ofInstant(java.time.Instant.ofEpochMilli(modifiedMs), java.time.ZoneId.systemDefault());
		}
		return new Entry(fileName, name, when, bytes);
	}

	private static String shownName(String label)
	{
		if (label.isEmpty())
		{
			return "session";
		}
		Matcher counted = COUNTED.matcher(label);
		return counted.matches() ? counted.group(1).replace('-', ' ') + "-" + counted.group(2) : label.replace('-', ' ');
	}

	/** Whether a file is a recording: its first line is a recording's header */
	static boolean isRecording(Filepath f)
	{
		try (BufferedReader r = f.openBufferedReader())
		{
			return isHeader(r.readLine());
		}
		catch (IOException | RuntimeException e)
		{
			return false;
		}
	}

	static boolean isHeader(String firstLine)
	{
		return firstLine != null && firstLine.trim().startsWith("{") && HEADER.matcher(firstLine).find();
	}

	/**
	 * The name an imported file gets in the sessions folder: kept if it has the recorder's time stamp,
	 * otherwise stamped with the file's own time so it sorts among the rest
	 */
	static String importName(String fileName, LocalDateTime fileTime)
	{
		Matcher m = FILE.matcher(fileName);
		if (m.matches())
		{
			// Keep its stamp and any number, but nothing a file name shouldn't hold
			Matcher counted = COUNTED.matcher(m.group(2));
			return m.group(1) + "-" + (counted.matches() ? Recording.safeLabel(counted.group(1)) + "_" + counted.group(2) : Recording.safeLabel(m.group(2))) + ".jsonl";
		}
		String base = fileName.toLowerCase().endsWith(".jsonl") ? fileName.substring(0, fileName.length() - 6) : fileName;
		return STAMP.format(fileTime) + "-" + Recording.safeLabel(base) + ".jsonl";
	}

	/** A recording's file name with a new name, keeping its time stamp */
	static String renamed(String fileName, String newName)
	{
		Matcher m = FILE.matcher(fileName);
		String stamp = m.matches() ? m.group(1) : STAMP.format(LocalDateTime.now());
		return stamp + "-" + Recording.safeLabel(newName) + ".jsonl";
	}

	/**
	 * A file name whose shown name no other recording in the folder has: a repeated name gets the next
	 * number, so TFA, then TFA-1, TFA-2... {@code existing} is the folder's file names, from {@link #names};
	 * the file called {@code except}, the one being renamed, is left out.
	 */
	static String numbered(Collection<String> existing, String fileName, String except)
	{
		List<String> files = new ArrayList<>();
		List<String> taken = new ArrayList<>();
		for (String name : existing)
		{
			if (!name.equals(except))
			{
				files.add(name.toLowerCase());
				taken.add(entry(name, 0, 0).name.toLowerCase());
			}
		}
		Matcher m = FILE.matcher(fileName);
		String stamp = m.matches() ? m.group(1) : STAMP.format(LocalDateTime.now());
		String label = m.matches() ? m.group(2) : Recording.safeLabel(fileName.replaceAll("(?i)\\.jsonl$", ""));
		if (isFree(files, stamp, label, taken))
		{
			return stamp + "-" + label + ".jsonl";
		}
		Matcher counted = COUNTED.matcher(label);
		String base = counted.matches() ? counted.group(1) : label;
		for (int n = 1; ; n++)
		{
			if (isFree(files, stamp, base + "_" + n, taken))
			{
				return stamp + "-" + base + "_" + n + ".jsonl";
			}
		}
	}

	private static boolean isFree(List<String> files, String stamp, String label, List<String> taken)
	{
		String file = stamp + "-" + label + ".jsonl";
		return !taken.contains(shownName(label).toLowerCase()) && !files.contains(file.toLowerCase());
	}
}

package com.encounterrecorder;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.HeadIcon;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.NpcOverrides;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Text;

/**
 * Turns game state into JSON. Coordinates are written twice: "x"/"y"/"p" are real world coordinates,
 * translated out of the instance when the player is in one, so they match the map in the game cache;
 * "sx"/"sy" are scene coordinates, which match the collision and height arrays in the scene line.
 */
final class Snap
{
	private Snap()
	{
	}

	static JsonObject line(String event, int tick, int cycle)
	{
		JsonObject o = new JsonObject();
		o.addProperty("t", tick);
		o.addProperty("c", cycle);
		o.addProperty("e", event);
		return o;
	}

	static void tile(JsonObject o, WorldView wv, LocalPoint lp)
	{
		if (wv != null)
		{
			tile(o, wv, lp, wv.getPlane());
		}
	}

	static void tile(JsonObject o, WorldView wv, LocalPoint lp, int plane)
	{
		if (wv == null || lp == null)
		{
			return;
		}
		Scene scene = wv.getScene();
		WorldPoint wp = WorldPoint.fromLocalInstance(scene, lp, plane);
		o.addProperty("x", wp.getX());
		o.addProperty("y", wp.getY());
		o.addProperty("p", wp.getPlane());
		// In an instance "p" is the floor of the template it was copied from; this is the scene's own floor
		o.addProperty("pl", plane);
		o.addProperty("sx", lp.getSceneX());
		o.addProperty("sy", lp.getSceneY());
		// Sub-tile position: 128 units per tile. Shows where a projectile lands or a big NPC's centre is
		o.addProperty("lx", lp.getX());
		o.addProperty("ly", lp.getY());
	}

	/** An actor's position on its own floor (not necessarily the floor you're on) */
	static void actorTile(JsonObject o, Actor actor)
	{
		WorldPoint wp = actor.getWorldLocation();
		WorldView wv = actor.getWorldView();
		tile(o, wv, actor.getLocalLocation(), wp != null ? wp.getPlane() : wv == null ? 0 : wv.getPlane());
	}

	/**
	 * Who an actor is, without their name: "me", an NPC by index and ID, or another player by index
	 */
	static JsonElement ref(Client client, Actor actor)
	{
		if (actor == null)
		{
			return JsonNull.INSTANCE;
		}
		JsonObject o = new JsonObject();
		if (actor == client.getLocalPlayer())
		{
			o.addProperty("k", "me");
		}
		else if (actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			o.addProperty("k", "npc");
			o.addProperty("i", npc.getIndex());
			o.addProperty("id", npc.getId());
		}
		else if (actor instanceof Player)
		{
			o.addProperty("k", "player");
			o.addProperty("i", ((Player) actor).getId());
		}
		else
		{
			o.addProperty("k", "other");
		}
		return o;
	}

	/**
	 * The tile the server has the actor on, which the drawn position ("x"/"y", "lx"/"ly") catches up to
	 * over the tick as the client animates the move. For NPCs bigger than one tile it is the south-west tile
	 */
	private static JsonObject serverTile(Actor actor)
	{
		WorldView wv = actor.getWorldView();
		WorldPoint wp = actor.getWorldLocation();
		if (wv == null || wp == null)
		{
			return null;
		}
		LocalPoint lp = LocalPoint.fromScene(wp.getX() - wv.getBaseX(), wp.getY() - wv.getBaseY(), wv);
		JsonObject t = new JsonObject();
		tile(t, wv, lp, wp.getPlane());
		t.remove("lx");
		t.remove("ly");
		return t;
	}

	/**
	 * Stand, stand-turn left and right, walk, walk back, walk left, walk right and run animations
	 */
	static JsonArray moveSet(Actor actor)
	{
		return ints(new int[]{
			actor.getIdlePoseAnimation(), actor.getIdleRotateLeft(), actor.getIdleRotateRight(),
			actor.getWalkAnimation(), actor.getWalkRotate180(), actor.getWalkRotateLeft(), actor.getWalkRotateRight(),
			actor.getRunAnimation()
		});
	}

	/**
	 * Per-NPC model, colour and texture changes on top of the cache definition, which some bosses use
	 */
	static void overrides(JsonObject o, NPC npc)
	{
		NpcOverrides overrides = npc.getModelOverrides();
		if (overrides == null)
		{
			return;
		}
		JsonObject v = new JsonObject();
		v.add("models", ints(overrides.getModelIds()));
		v.add("colors", shorts(overrides.getColorToReplaceWith()));
		v.add("textures", shorts(overrides.getTextureToReplaceWith()));
		v.addProperty("useLocalPlayer", overrides.useLocalPlayer());
		o.add("overrides", v);
	}

	static JsonArray spotAnims(Actor actor)
	{
		JsonArray list = new JsonArray();
		for (ActorSpotAnim spot : actor.getSpotAnims())
		{
			JsonObject s = new JsonObject();
			s.addProperty("id", spot.getId());
			s.addProperty("h", spot.getHeight());
			s.addProperty("start", spot.getStartCycle());
			s.addProperty("f", spot.getFrame());
			list.add(s);
		}
		return list;
	}

	/**
	 * What any actor is doing this tick
	 */
	static JsonObject actor(Client client, Actor actor)
	{
		JsonObject o = new JsonObject();
		o.add("who", ref(client, actor));
		actorTile(o, actor);
		JsonObject server = serverTile(actor);
		if (server != null)
		{
			o.add("tile", server);
		}
		o.addProperty("o", actor.getCurrentOrientation());
		if (actor.getOrientation() != actor.getCurrentOrientation())
		{
			// Still turning: where it will end up facing
			o.addProperty("of", actor.getOrientation());
		}
		o.addProperty("a", actor.getAnimation());
		o.addProperty("af", actor.getAnimationFrame());
		o.addProperty("pose", actor.getPoseAnimation());
		JsonArray spots = spotAnims(actor);
		if (spots.size() > 0)
		{
			o.add("spot", spots);
		}
		if (actor.getHealthRatio() >= 0)
		{
			JsonArray hp = new JsonArray();
			hp.add(actor.getHealthRatio());
			hp.add(actor.getHealthScale());
			o.add("hp", hp);
		}
		if (actor.getInteracting() != null)
		{
			o.add("int", ref(client, actor.getInteracting()));
		}
		if (actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			int[] archives = npc.getOverheadArchiveIds();
			short[] sprites = npc.getOverheadSpriteIds();
			if (archives != null && sprites != null)
			{
				JsonArray icons = new JsonArray();
				for (int i = 0; i < Math.min(archives.length, sprites.length); i++)
				{
					if (archives[i] >= 0)
					{
						JsonArray icon = new JsonArray();
						icon.add(archives[i]);
						icon.add(sprites[i]);
						icons.add(icon);
					}
				}
				if (icons.size() > 0)
				{
					o.add("head", icons);
				}
			}
		}
		else if (actor instanceof Player)
		{
			Player player = (Player) actor;
			HeadIcon icon = player.getOverheadIcon();
			if (icon != null)
			{
				o.addProperty("head", icon.name());
			}
			if (player.getSkullIcon() != -1)
			{
				o.addProperty("skull", player.getSkullIcon());
			}
		}
		return o;
	}

	/**
	 * What a player looks like. "equip" is the game's own 12-slot body array in KitType order: values of
	 * ITEM_OFFSET and up are worn items (subtract it for the item ID), KIT_OFFSET and up are body kits
	 * (subtract it for the kit ID), 0 is an empty slot. "colors" are the body colour indices
	 */
	static void look(JsonObject o, Client client, Player player, PlayerComposition comp)
	{
		o.add("who", ref(client, player));
		o.addProperty("gender", comp.getGender());
		o.addProperty("cb", player.getCombatLevel());
		o.addProperty("team", player.getTeam());
		o.add("equip", ints(comp.getEquipmentIds()));
		o.add("colors", ints(comp.getColors()));
		o.addProperty("itemOffset", PlayerComposition.ITEM_OFFSET);
		o.addProperty("kitOffset", PlayerComposition.KIT_OFFSET);
		if (comp.getTransformedNpcId() != -1)
		{
			o.addProperty("npc", comp.getTransformedNpcId());
		}
	}

	/**
	 * Everything the cache says about an NPC that a replica needs: written once per NPC ID per session
	 */
	static JsonObject npcDefinition(NPC npc)
	{
		NPCComposition def = npc.getTransformedComposition();
		if (def == null)
		{
			def = npc.getComposition();
		}
		JsonObject o = new JsonObject();
		o.addProperty("id", def.getId());
		o.addProperty("name", Text.removeTags(def.getName()));
		o.addProperty("size", def.getSize());
		o.addProperty("level", def.getCombatLevel());
		o.add("models", ints(def.getModels()));
		o.add("stats", ints(def.getStats()));
		o.add("actions", strings(def.getActions()));
		o.addProperty("widthScale", def.getWidthScale());
		o.addProperty("heightScale", def.getHeightScale());
		if (def.getId() != npc.getId())
		{
			o.addProperty("baseId", npc.getId());
		}
		return o;
	}

	static JsonObject objectDefinition(ObjectComposition def)
	{
		JsonObject o = new JsonObject();
		o.addProperty("id", def.getId());
		o.addProperty("name", Text.removeTags(def.getName()));
		o.addProperty("sizeX", def.getSizeX());
		o.addProperty("sizeY", def.getSizeY());
		o.add("actions", strings(def.getActions()));
		o.add("impostors", ints(def.getImpostorIds()));
		return o;
	}

	static JsonObject object(TileObject obj)
	{
		JsonObject o = new JsonObject();
		o.addProperty("id", obj.getId());
		// The object's own floor, not the one you're standing on: scenes hold every floor at once
		tile(o, obj.getWorldView(), obj.getLocalLocation(), obj.getPlane());
		o.addProperty("pl", obj.getPlane());
		if (obj instanceof GameObject)
		{
			GameObject g = (GameObject) obj;
			o.addProperty("kind", "game");
			o.addProperty("orient", g.getOrientation());
			o.addProperty("config", g.getConfig());
			o.addProperty("w", g.getSceneMaxLocation().getX() - g.getSceneMinLocation().getX() + 1);
			o.addProperty("l", g.getSceneMaxLocation().getY() - g.getSceneMinLocation().getY() + 1);
			animation(o, g.getRenderable());
		}
		else if (obj instanceof WallObject)
		{
			WallObject w = (WallObject) obj;
			o.addProperty("kind", "wall");
			o.addProperty("orientA", w.getOrientationA());
			o.addProperty("orientB", w.getOrientationB());
			o.addProperty("config", w.getConfig());
			animation(o, w.getRenderable1());
		}
		else if (obj instanceof DecorativeObject)
		{
			DecorativeObject d = (DecorativeObject) obj;
			o.addProperty("kind", "decor");
			o.addProperty("config", d.getConfig());
			animation(o, d.getRenderable());
		}
		else if (obj instanceof GroundObject)
		{
			GroundObject g = (GroundObject) obj;
			o.addProperty("kind", "ground");
			o.addProperty("config", g.getConfig());
			animation(o, g.getRenderable());
		}
		return o;
	}

	private static void animation(JsonObject o, Renderable renderable)
	{
		if (renderable instanceof DynamicObject)
		{
			Animation anim = ((DynamicObject) renderable).getAnimation();
			if (anim != null)
			{
				o.addProperty("anim", anim.getId());
			}
		}
	}

	/**
	 * A clicked menu entry, with player names taken out of the target
	 */
	static String menuTarget(MenuAction action, String target)
	{
		if (action == null || target == null)
		{
			return target == null ? null : Text.removeTags(target);
		}
		switch (action)
		{
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
			case WIDGET_TARGET_ON_PLAYER:
			case RUNELITE_PLAYER:
				return "<player>";
			default:
				return Text.removeTags(target);
		}
	}

	static JsonArray ints(int[] values)
	{
		JsonArray list = new JsonArray();
		if (values != null)
		{
			for (int v : values)
			{
				list.add(v);
			}
		}
		return list;
	}

	/** A screen rectangle as [x, y, width, height] in canvas pixels */
	static JsonArray rect(java.awt.Rectangle r)
	{
		JsonArray a = new JsonArray();
		a.add(r.x);
		a.add(r.y);
		a.add(r.width);
		a.add(r.height);
		return a;
	}

	static JsonArray shorts(short[] values)
	{
		JsonArray list = new JsonArray();
		if (values != null)
		{
			for (short v : values)
			{
				list.add(v);
			}
		}
		return list;
	}

	static JsonArray strings(String[] values)
	{
		JsonArray list = new JsonArray();
		if (values != null)
		{
			for (String v : values)
			{
				list.add(v == null ? JsonNull.INSTANCE : new JsonPrimitive(v));
			}
		}
		return list;
	}

	static JsonArray grid(int[][] values)
	{
		JsonArray rows = new JsonArray();
		for (int[] row : values)
		{
			rows.add(ints(row));
		}
		return rows;
	}
}

package com.encounterrecorder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class EncounterRecorderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(EncounterRecorderPlugin.class);
		RuneLite.main(args);
	}
}

package com.encounterrecorder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

public class PrivacyAndParsingTest
{
	@Test
	public void playerTargetsLoseTheirName()
	{
		assertEquals("<player>", Snap.menuTarget(MenuAction.PLAYER_SECOND_OPTION, "<col=ffffff>Zezima<col=ff00>  (level-126)"));
		assertEquals("<player>", Snap.menuTarget(MenuAction.WIDGET_TARGET_ON_PLAYER, "Ice Barrage -> Zezima"));
	}

	@Test
	public void hiddenNamesAreTakenOutOfTextHoweverTheyreWritten()
	{
		Set<String> names = Set.of("Mr Gnome", "Zezima", "Bob");
		assertEquals("<player> wishes to trade with you.", Names.scrub("Mr Gnome wishes to trade with you.", names));
		assertEquals("Walk here <player>  (level-126)", Names.scrub("Walk here zezima  (level-126)", names));
		assertEquals("<player> and <player>", Names.scrub("Mr\u00A0Gnome and mr_gnome", names));
		// Only whole names: "Bobcat" isn't Bob
		assertEquals("A Bobcat bites <player>.", Names.scrub("A Bobcat bites Bob.", names));
		assertEquals("No names here", Names.scrub("No names here", names));
	}

	@Test
	public void recordingsAreListedByTheirNameNewestFirst()
	{
		assertEquals("Demo", Recordings.entry("20261026-232157-Demo.jsonl", 0, 1).name);
		assertEquals("vardorvis p2", Recordings.entry("20261025-101500-vardorvis-p2.jsonl", 0, 1).name);
		assertEquals("my-own-file", Recordings.entry("my-own-file.jsonl", 0, 1).name);
		assertEquals(2026, Recordings.entry("20261026-232157-Demo.jsonl", 0, 1).when.getYear());
	}

	@Test
	public void importedAndRenamedRecordingsKeepTheirPlaceInTime()
	{
		java.time.LocalDateTime t = java.time.LocalDateTime.of(2026, 10, 27, 9, 5, 0);
		assertEquals("20261026-232157-Demo.jsonl", Recordings.importName("20261026-232157-Demo.jsonl", t));
		assertEquals("20261027-090500-demo-ticks-8-16.jsonl", Recordings.importName("demo-ticks-8-16.jsonl", t));
		assertEquals("20261026-232157-Poopsoul-fight.jsonl", Recordings.renamed("20261026-232157-Demo.jsonl", "Poopsoul fight"));
	}

	@Test
	public void onlyRecordingsCanBeImported()
	{
		assertTrue(Recordings.isHeader("{\"t\":0,\"c\":1,\"e\":\"header\",\"format\":5}"));
		assertFalse(Recordings.isHeader("hello"));
		assertFalse(Recordings.isHeader(null));
		// An imported name keeps its stamp and number but loses anything a file name shouldn't hold
		assertEquals("20261026-232157-TFA_2.jsonl", Recordings.importName("20261026-232157-TFA_2.jsonl", java.time.LocalDateTime.now()));
		assertEquals("20261026-232157-a-b.jsonl", Recordings.importName("20261026-232157-a:b.jsonl", java.time.LocalDateTime.now()));
	}

	@Test
	public void repeatedNamesGetTheNextNumber()
	{
		java.util.List<String> folder = new java.util.ArrayList<>();
		String first = Recordings.numbered(folder, "20261027-100000-TFA.jsonl", null);
		assertEquals("20261027-100000-TFA.jsonl", first);
		folder.add(first);
		String second = Recordings.numbered(folder, "20261027-110000-TFA.jsonl", null);
		assertEquals("20261027-110000-TFA_1.jsonl", second);
		folder.add(second);
		assertEquals("20261027-120000-TFA_2.jsonl", Recordings.numbered(folder, "20261027-120000-TFA.jsonl", null));
		assertEquals("TFA-1", Recordings.entry(second, 0, 0).name);
		// Importing a numbered one that's taken moves on to the next number; renaming a file to its own name keeps it
		assertEquals("20261027-110000-TFA_2.jsonl", Recordings.numbered(folder, second, null));
		assertEquals(second, Recordings.numbered(folder, second, second));
		// Same name, any case
		assertEquals("20261027-130000-tfa_2.jsonl", Recordings.numbered(folder, "20261027-130000-tfa.jsonl", null));
	}

	@Test
	public void replayLinksCarryOnlyTheFileName()
	{
		assertEquals("https://encounter-replay.pages.dev/#session=20261026-131912-GE2.jsonl",
			EncounterRecorderPlugin.replayLink("20261026-131912-GE2.jsonl"));
		assertEquals("https://encounter-replay.pages.dev/", EncounterRecorderPlugin.replayLink(null));
	}

	@Test
	public void bankPinInterfacesAreRecognised()
	{
		assertTrue(EncounterRecorderPlugin.isBankPinInterface(InterfaceID.BANKPIN_KEYPAD));
		assertTrue(EncounterRecorderPlugin.isBankPinInterface(InterfaceID.BANKPIN_SETTINGS));
		assertFalse(EncounterRecorderPlugin.isBankPinInterface(InterfaceID.INVENTORY));
	}

	@Test
	public void onlyLocalChatIsEverRecordedFromPlayers()
	{
		assertEquals(EncounterRecorderPlugin.ChatKind.LOCAL, EncounterRecorderPlugin.chatKind(ChatMessageType.PUBLICCHAT));
		assertEquals(EncounterRecorderPlugin.ChatKind.LOCAL, EncounterRecorderPlugin.chatKind(ChatMessageType.AUTOTYPER));
		assertEquals(EncounterRecorderPlugin.ChatKind.GAME, EncounterRecorderPlugin.chatKind(ChatMessageType.GAMEMESSAGE));
		for (ChatMessageType never : new ChatMessageType[]{
			ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT, ChatMessageType.MODPRIVATECHAT,
			ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT,
			ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.FRIENDNOTIFICATION, ChatMessageType.TRADEREQ,
			ChatMessageType.BROADCAST, ChatMessageType.LOGINLOGOUTNOTIFICATION})
		{
			assertEquals(never.name(), EncounterRecorderPlugin.ChatKind.NEVER, EncounterRecorderPlugin.chatKind(never));
		}
	}

	@Test
	public void npcTargetsKeepTheirNameWithoutTags()
	{
		assertEquals("Vardorvis  (level-1040)", Snap.menuTarget(MenuAction.NPC_SECOND_OPTION, "<col=ffff00>Vardorvis<col=ff00>  (level-1040)"));
	}

	@Test
	public void autoRecordIdsIgnoreJunk()
	{
		Set<Integer> ids = EncounterRecorderPlugin.parseIds(" 16677, abc ,12223,, ");
		assertEquals(2, ids.size());
		assertTrue(ids.contains(16677));
		assertTrue(ids.contains(12223));
		assertTrue(EncounterRecorderPlugin.parseIds(null).isEmpty());
	}

	@Test
	public void labelsAreSafeFileNames()
	{
		assertEquals("Vardorvis-p2", Recording.safeLabel("  Vardorvis / p2?  "));
		assertEquals("session", Recording.safeLabel("<>:"));
		assertEquals("session", Recording.safeLabel(null));
		assertEquals(40, Recording.safeLabel("a".repeat(100)).length());
	}
}
